package com.autoops.files.service;import io.minio.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.io.InputStream;@Service public class ObjectStorageService{private final MinioClient minio;private final String bucket;public ObjectStorageService(@Value("${autoops.minio.endpoint:http://minio:9000}")String endpoint,@Value("${autoops.minio.access-key:autoops}")String access,@Value("${autoops.minio.secret-key:autoops-secret}")String secret,@Value("${autoops.minio.bucket:autoops}")String bucket){this.minio=MinioClient.builder().endpoint(endpoint).credentials(access,secret).build();this.bucket=bucket;}public void put(String key,InputStream in,long size,String type){try{if(!minio.bucketExists(BucketExistsArgs.builder().bucket(bucket).build()))minio.makeBucket(MakeBucketArgs.builder().bucket(bucket).build());minio.putObject(PutObjectArgs.builder().bucket(bucket).object(key).stream(in,size,-1).contentType(type).build());}catch(Exception e){throw new IllegalStateException("Object storage failed",e);}}public InputStream get(String key){try{return minio.getObject(GetObjectArgs.builder().bucket(bucket).object(key).build());}catch(Exception e){throw new IllegalStateException("Object storage failed",e);}}}
